-- ===== Part 3: tenant resolution for action routes (TenantGuard) =====
CREATE FUNCTION pcp_resolve_action_object(p_kind text, p_id uuid, p_user uuid)
  RETURNS TABLE (organization_id uuid, product_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT r.organization_id, r.product_id FROM action_requests r
    JOIN organization_members m ON m.organization_id = r.organization_id AND m.user_id = p_user
    WHERE p_kind = 'action_request' AND r.id = p_id
    UNION ALL
    SELECT p.organization_id, p.product_id FROM action_policies p
    JOIN organization_members m ON m.organization_id = p.organization_id AND m.user_id = p_user
    WHERE p_kind = 'action_policy' AND p.id = p_id
  $$;

ALTER FUNCTION pcp_resolve_action_object(text, uuid, uuid) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_resolve_action_object(text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_resolve_action_object(text, uuid, uuid) TO pcp_app;
